        public static func listImapPresets() -> Endpoint<[MailImapPreset]> {
            Endpoint(method: .get, path: "/api/mail/imap-presets")
        }

        /// `POST /api/mail/accounts/imap`
        ///
        /// Connect an IMAP account: tests the login (read-only) before anything is saved, stores the
        /// password encrypted, and starts the first header sync.
        public static func connectImap(body: MailImapConnect) -> Endpoint<MailAccountOut> {
            Endpoint(method: .post, path: "/api/mail/accounts/imap", body: body)
        }

        /// `POST /api/mail/accounts/{account_id}/sync`
        ///
        /// Refresh one account's headers now (reads the mailbox; changes nothing in it).
        public static func syncNow(accountId: Int) -> Endpoint<MailSyncOut> {
            Endpoint(method: .post, path: "/api/mail/accounts/\(Wire.segment(accountId))/sync")
        }

        public enum ListMessagesFolder: OpenEnum {
            case inbox
            case sent
            /// A value this build does not know (the server is newer than the app).
            case unknown(String)

            public static let allCases: [Self] = [.inbox, .sent]

            public init(rawValue: String) {
                switch rawValue {
                case "inbox": self = .inbox
                case "sent": self = .sent
                default: self = .unknown(rawValue)
                }
            }

            public var rawValue: String {
                switch self {
                case .inbox: "inbox"
                case .sent: "sent"
                case .unknown(let raw): raw
                }
            }
        }

        /// `GET /api/mail/messages`
        ///
        /// Mirrored headers, newest first. Never touches a mailbox.
        ///
        /// - Parameters:
        ///   - account: An account id (see accounts)
        ///   - since: Local date, inclusive
        ///   - until: Local date, inclusive
        ///   - q: Matches subject, sender or recipients, any case
        ///   - sender: Matches the sender's name or address
        public static func listMessages(account: Int? = nil, folder: ListMessagesFolder? = nil, since: LocalDate? = nil, until: LocalDate? = nil, q: String? = nil, sender: String? = nil, limit: Int? = nil) -> Endpoint<MailMessageList> {
            Endpoint(method: .get, path: "/api/mail/messages", query: Wire.query([("account", account), ("folder", folder), ("since", since), ("until", until), ("q", q), ("sender", sender), ("limit", limit)]))
        }

        /// `GET /api/mail/messages/{message_id}`
        ///
        /// One message, fetched from its mailbox now and cleaned. The mailbox is not changed (it is
        /// not even marked read).
        public static func readMessage(messageId: Int) -> Endpoint<MailMessageDetail> {
            Endpoint(method: .get, path: "/api/mail/messages/\(Wire.segment(messageId))")
        }
    }

    public enum Reminders {
        /// `GET /api/reminders`
        ///
        /// Open reminders by due date (undated last), then completed ones, newest first.
        ///
        /// - Parameters:
        ///   - list: Only this list (an id from /lists)
        ///   - includeCompleted: Also reminders completed (last 30 days)
        ///   - dated: true: only with a due date; false: only without
        public static func listReminders(list: String? = nil, includeCompleted: Bool? = nil, dated: Bool? = nil, limit: Int? = nil) -> Endpoint<[ReminderOut]> {
            Endpoint(method: .get, path: "/api/reminders", query: Wire.query([("list", list), ("include_completed", includeCompleted), ("dated", dated), ("limit", limit)]))
        }

        /// `POST /api/reminders`
        ///
        /// Queue a new reminder. It is shown at once and keeps its id when the provider reports it.
        /// Google Tasks lists refuse a due time and a priority (422).
        public static func createReminder(body: ReminderCreate) -> Endpoint<ReminderOut> {
            Endpoint(method: .post, path: "/api/reminders", body: body)
        }

        /// `GET /api/reminders/lists`
        ///
        /// Every list: Apple Reminders first, then each Google account's task lists.
        public static func reminderLists() -> Endpoint<[ReminderListOut]> {
            Endpoint(method: .get, path: "/api/reminders/lists")
        }

        /// `GET /api/reminders/status`
        ///
        /// Each source's freshness, whether the helper is polling, and what is queued or failed.
        public static func remindersStatus() -> Endpoint<ReminderStatusOut> {
            Endpoint(method: .get, path: "/api/reminders/status")
        }

        /// `POST /api/reminders/sync`
        ///
        /// Poll every Google Tasks account now (and retry pending Google ops). Apple Reminders
        /// syncs whenever the Mac helper pushes.
        public static func syncNow() -> Endpoint<[ReminderSyncOutcomeOut]> {
            Endpoint(method: .post, path: "/api/reminders/sync")
        }

        public enum ListOpsState: OpenEnum {
            case pending
            case applied
            case failed
            /// A value this build does not know (the server is newer than the app).
            case unknown(String)

            public static let allCases: [Self] = [.pending, .applied, .failed]

            public init(rawValue: String) {
                switch rawValue {
                case "pending": self = .pending
                case "applied": self = .applied
                case "failed": self = .failed
                default: self = .unknown(rawValue)
                }
            }

            public var rawValue: String {
                switch self {
                case .pending: "pending"
                case .applied: "applied"
                case .failed: "failed"
                case .unknown(let raw): raw
                }
            }
        }

        /// `GET /api/reminders/ops`
        ///
        /// Queued changes, newest first.
        ///
        /// - Parameters:
        ///   - state: Default: pending and failed
        public static func listOps(state: ListOpsState? = nil, reminderId: Int? = nil, limit: Int? = nil) -> Endpoint<[ReminderOpOut]> {
            Endpoint(method: .get, path: "/api/reminders/ops", query: Wire.query([("state", state), ("reminder_id", reminderId), ("limit", limit)]))
        }

        /// `DELETE /api/reminders/ops/{op_id}`
        ///
        /// Withdraw a pending or failed op. Withdrawing a create the provider never got removes the
        /// reminder from the organizer. If the helper already picked the op up, its change may still
        /// land; the next push shows what Apple Reminders holds.
        public static func withdrawOp(opId: Int) -> Endpoint<NoContent> {
            Endpoint(method: .delete, path: "/api/reminders/ops/\(Wire.segment(opId))")
        }

        /// `POST /api/reminders/ops/{op_id}/retry`
        ///
        /// Queue a failed op again. A Google op is applied again at once.
        public static func retryOp(opId: Int) -> Endpoint<ReminderOpOut> {
            Endpoint(method: .post, path: "/api/reminders/ops/\(Wire.segment(opId))/retry")
        }

        /// `GET /api/reminders/{reminder_id}`
        ///
        /// Get Reminder
        public static func getReminder(reminderId: Int) -> Endpoint<ReminderOut> {
            Endpoint(method: .get, path: "/api/reminders/\(Wire.segment(reminderId))")
        }

        /// `PATCH /api/reminders/{reminder_id}`
        ///
        /// Queue a change to the fields sent. Clearing due_date also clears due_time.
        public static func updateReminder(reminderId: Int, body: ReminderUpdate) -> Endpoint<ReminderOut> {
            Endpoint(method: .patch, path: "/api/reminders/\(Wire.segment(reminderId))", body: body)
        }

        /// `POST /api/reminders/{reminder_id}/complete`
        ///
        /// Queue a completion. Completing a completed reminder queues nothing.
        public static func completeReminder(reminderId: Int) -> Endpoint<ReminderOut> {
            Endpoint(method: .post, path: "/api/reminders/\(Wire.segment(reminderId))/complete")
        }

        /// `POST /api/reminders/{reminder_id}/uncomplete`
        ///
        /// Queue un-completing. An open reminder queues nothing.
        public static func uncompleteReminder(reminderId: Int) -> Endpoint<ReminderOut> {
            Endpoint(method: .post, path: "/api/reminders/\(Wire.segment(reminderId))/uncomplete")
        }
    }

    public enum Settings {
