        }

        /// `GET /api/settings/accounts`
        ///
        /// List Accounts
        public static func listAccounts() -> Endpoint<[ProviderAccountOut]> {
            Endpoint(method: .get, path: "/api/settings/accounts")
        }

        /// `PATCH /api/settings/accounts/{account_id}`
        ///
        /// Update Account
        public static func updateAccount(accountId: Int, body: ProviderAccountUpdate) -> Endpoint<ProviderAccountOut> {
            Endpoint(method: .patch, path: "/api/settings/accounts/\(Wire.segment(accountId))", body: body)
        }

        /// `DELETE /api/settings/accounts/{account_id}`
        ///
        /// Remove the account and its stored credentials. Data mirrored from it goes with it
        /// (each feature module deletes its mirrored rows on the next sync). A Google account's grant
        /// is also revoked at Google, best effort.
        public static func deleteAccount(accountId: Int) -> Endpoint<NoContent> {
            Endpoint(method: .delete, path: "/api/settings/accounts/\(Wire.segment(accountId))")
        }

        /// `GET /api/settings/google`
