        public static func start(body: GoogleStart) -> Endpoint<GoogleStartOut> {
            Endpoint(method: .post, path: "/api/settings/google/start", body: body)
        }

        /// `GET /api/oauth/google/callback`
        ///
        /// Google's redirect. Always answers with a redirect back to Settings, carrying only a fixed
        /// result code: anyone can craft a link to this URL, so no text from it reaches the page.
        public static func callback(state: String? = nil, code: String? = nil, error: String? = nil) -> Endpoint<NoContent> {
            Endpoint(method: .get, path: "/api/oauth/google/callback", query: Wire.query([("state", state), ("code", code), ("error", error)]))
        }
    }

